import { Component, OnInit } from '@angular/core';
import { ApiService } from '../../services/api.service';

@Component({
  selector: 'app-grid',
  templateUrl: './grid.component.html',
  styleUrls: ['./grid.component.css']
})
export class GridComponent implements OnInit {
  contratos: any[] = [];

  constructor(private api: ApiService) {}

  ngOnInit(): void {
    this.api.getContratos().subscribe({
      next: (res) => this.contratos = res,
      error: (err) => console.error('Error al obtener contratos:', err)
    });
  }
}

<h2>Contratos</h2>
<table>
  <thead>
    <tr>
      <th>ID</th>
      <th>Nombre</th>
      <th>Fecha inicio</th>
      <th>Activo</th>
    </tr>
  </thead>
  <tbody>
    <tr *ngFor="let c of contratos">
      <td>{{ c.id }}</td>
      <td>{{ c.nombre || c.title || c.name }}</td>
      <td>{{ c.fecha_inicio || c.start_date || c.date }}</td>
      <td>{{ c.activo ? 'Sí' : 'No' }}</td>
    </tr>
  </tbody>
</table>
